async function syncNodeUsers(nodeId) {
  try {
    const node = await db_default.node.findUnique({ where: { id: nodeId } });
    if (!node || !node.isActive) return { total: 0, success: 0 };
    const inbounds = await db_default.subscriptionInbound.findMany({
      where: { nodeId: node.id }
    });
    console.log(`[Sync] Syncing ${inbounds.length} active UUIDs to node ${node.name} (${node.id})...`);
    let successCount = 0;
    for (const inb of inbounds) {
      const email = `${inb.subscriptionId}_${inb.inboundTag}_${inb.xrayUuid}`;
      const ok = await addVlessUser(node.apiHost, inb.inboundTag, email, inb.xrayUuid);
      if (ok) successCount++;
    }
    console.log(`[Sync] Node ${node.name}: ${successCount}/${inbounds.length} users synced successfully.`);
    return { total: inbounds.length, success: successCount };
  } catch (e) {
    console.error(`[Sync] Failed to sync users for node ${nodeId}:`, e);
    return { total: 0, success: 0 };
  }
}

// src/lib/userService.ts
async function createUserService(params) {
  const name = params.name?.trim() || null;
  const email = params.email?.trim() || (name ? `${name.toLowerCase()}@internal` : null);
  const subName = params.subName?.trim() || `${name || "Default"}'s Device`;
  const role = params.role === "ADMIN" ? "ADMIN" : "USER";
  const authentikId = `cli_${import_crypto.default.randomUUID()}`;
  const user = await db_default.user.create({
    data: {
      authentikId,
      email,
      name,
      role
    }
  });
  let targetNode = null;
  if (params.nodeId) {
    targetNode = await db_default.node.findUnique({ where: { id: params.nodeId } });
  }
  if (!targetNode) {
    targetNode = await db_default.node.findFirst({ where: { isActive: true } });
  }
  if (!targetNode) {
    targetNode = await db_default.node.findFirst();
  }
  if (!targetNode) {
    targetNode = await db_default.node.create({
      data: {
        name: "Main Server",
        address: process.env.XRAY_SERVER_DOMAIN || "nada.mu",
        port: 443,
        xrayPort: 7999,
        apiHost: process.env.XRAY_API_URL || "unix:///app/xray/api.sock"
      }
    });
  }
  const subToken = import_crypto.default.randomUUID();
  const subscription = await db_default.subscription.create({
    data: {
      token: subToken,
      name: subName,
      userId: user.id,
      nodeId: targetNode.id
    }
  });
  const activeNodes = await db_default.node.findMany({ where: { isActive: true } });
  const createdInbounds = [];
  for (const node of activeNodes) {
    const nodeTags = await getXrayInboundTags(node.apiHost);
    for (const tag of nodeTags) {
      const newUuid = import_crypto.default.randomUUID();
      const inb = await db_default.subscriptionInbound.create({
        data: {
          subscriptionId: subscription.id,
          nodeId: node.id,
          inboundTag: tag,
          xrayUuid: newUuid
        }
      });
      await db_default.uuidHistory.create({
        data: {
          subscriptionId: subscription.id,
          nodeId: node.id,
          inboundTag: tag,
          xrayUuid: newUuid
        }
      });
      try {
        const xrayEmail = `${subscription.id}_${tag}_${newUuid}`;
        await addVlessUser(node.apiHost, tag, xrayEmail, newUuid);
      } catch (err) {
        console.error(`[userService] Error registering user in Xray node ${node.name}:`, err);
      }
      createdInbounds.push({
        nodeName: node.name,
        nodeAddress: node.address,
        nodePort: node.port,
        inboundTag: tag,
        uuid: newUuid
      });
    }
  }
  return {
    user,
    subscription,
    inbounds: createdInbounds
  };
}
async function listUsersService() {
  const users = await db_default.user.findMany({
    include: {
      subscriptions: {
        include: {
          node: true,
          inbounds: true,
          traffic: true
        }
      }
    },
    orderBy: { createdAt: "desc" }
  });
  return users.map((u) => {
    let totalUp = BigInt(0);
    let totalDown = BigInt(0);
    for (const sub of u.subscriptions) {
      for (const t of sub.traffic) {
        totalUp += t.up;
        totalDown += t.down;
      }
    }
    return {
      id: u.id,
      name: u.name || "Unnamed",
      email: u.email || "\u2014",
      role: u.role,
      createdAt: u.createdAt,
      subscriptionsCount: u.subscriptions.length,
      subscriptions: u.subscriptions.map((s) => ({
        id: s.id,
        name: s.name,
        token: s.token,
        nodeName: s.node.name,
        inboundCount: s.inbounds.length,
        lastFetched: s.lastFetched
      })),
      totalUp,
      totalDown,
      totalBytes: totalUp + totalDown
    };
  });
}
async function getUserDetailsService(identifier) {
  const trimmed = identifier.trim();
  let sub = await db_default.subscription.findUnique({
    where: { token: trimmed },
    include: {
      user: true,
      node: true,
      inbounds: { include: { node: true } },
      traffic: true
    }
  });
  if (!sub) {
    const user = await db_default.user.findFirst({
      where: {
        OR: [{ id: trimmed }, { email: trimmed }, { name: trimmed }]
      },
      include: {
        subscriptions: {
          include: {
            user: true,
            node: true,
            inbounds: { include: { node: true } },
            traffic: true
          }
        }
      }
    });
    if (user && user.subscriptions.length > 0) {
      sub = user.subscriptions[0];
    }
  }
  if (!sub) {
    return null;
  }
  let totalUp = BigInt(0);
  let totalDown = BigInt(0);
  for (const t of sub.traffic) {
    totalUp += t.up;
    totalDown += t.down;
  }
  const links = [];
  for (const inb of sub.inbounds) {
    try {
      const link = await buildClientLink(
        inb.inboundTag,
        inb.xrayUuid,
        sub.name || inb.node.name,
        inb.node.address,
        inb.node.port,
        {
          sni: inb.node.realityServerName,
          pbk: inb.node.realityPubKey,
          sid: inb.node.realityShortId
        }
      );
      links.push({
        tag: inb.inboundTag,
        nodeName: inb.node.name,
        link
      });
    } catch (err) {
      console.error(`[userService] Failed to generate link for inbound ${inb.inboundTag}:`, err);
    }
  }
  const baseDomain = process.env.BASE_DOMAIN || process.env.AUTH_URL || "https://dash.test.nada.mu";
  const subUrl = `${baseDomain}/s/${sub.token}`;
  return {
    user: sub.user,
    subscription: {
      id: sub.id,
      name: sub.name,
      token: sub.token,
      createdAt: sub.createdAt,
      lastFetched: sub.lastFetched,
      node: sub.node
    },
    traffic: {
      up: totalUp,
      down: totalDown,
      total: totalUp + totalDown
    },
    subUrl,
    links
  };
}
async function deleteUserService(identifier) {
  const details = await getUserDetailsService(identifier);
  if (!details) {
    return { success: false, error: "User or subscription not found" };
  }
  const sub = details.subscription;
  const inbounds = await db_default.subscriptionInbound.findMany({
    where: { subscriptionId: sub.id },
    include: { node: true }
  });
  for (const inb of inbounds) {
    try {
      const xrayEmail = `${sub.id}_${inb.inboundTag}_${inb.xrayUuid}`;
      await removeVlessUser(inb.node.apiHost, inb.inboundTag, xrayEmail);
    } catch (err) {
      console.error(`[userService] Error removing VLESS user from node ${inb.node.name}:`, err);
    }
  }
  await db_default.user.delete({
    where: { id: details.user.id }
  });
  return { success: true, deletedUser: details.user.name || details.user.email };
}
async function resetUserTrafficService(identifier) {
  const details = await getUserDetailsService(identifier);
  if (!details) {
    return { success: false, error: "User or subscription not found" };
  }
  await db_default.trafficLog.deleteMany({
    where: { subscriptionId: details.subscription.id }
  });
  await db_default.uuidTrafficLog.deleteMany({
    where: { subscriptionId: details.subscription.id }
  });
  return { success: true };
}
async function syncAllNodesService() {
  const nodes = await db_default.node.findMany({ where: { isActive: true } });
  const results = [];
  for (const node of nodes) {
    const res = await syncNodeUsers(node.id);
    results.push({
      nodeId: node.id,
      nodeName: node.name,
      total: res.total,
      synced: res.success
    });
  }
  return results;
}

// src/cli/dashctl.ts
function formatBytes(bytes) {
  const b = typeof bytes === "bigint" ? bytes : BigInt(bytes || 0);
  if (b === BigInt(0)) return "0 B";
  const k = BigInt(1024);
  const sizes = ["B", "KB", "MB", "GB", "TB"];
  const i = Math.floor(Math.log(Number(b)) / Math.log(Number(k)));
  return `${(Number(b) / Math.pow(Number(k), i)).toFixed(2)} ${sizes[i]}`;
}
async function renderQr(text) {
  return new Promise((resolve) => {
    import_qrcode.default.toString(text, { type: "terminal", small: true }, (err, str) => {
      if (err) resolve(`[QR error: ${err.message}]`);
      else resolve(str);
    });
  });
}
function printHelp() {
  console.log(`
\x1B[1m\x1B[36m\u26A1 NadamuDash Control CLI (dashctl)\x1B[0m
Minimalistic, headless Xray control plane

\x1B[1mUSAGE:\x1B[0m
  dashctl <command> [subcommand] [arguments]

\x1B[1mCOMMANDS:\x1B[0m
  \x1B[32mstatus\x1B[0m                       Check database and Xray gRPC socket status
  \x1B[32msync\x1B[0m                         Sync all active users from DB into Xray in-memory state
  
  \x1B[32muser list\x1B[0m                    List all registered users and traffic usage
  \x1B[32muser add <name> [flags]\x1B[0m      Create a new user and generate subscription
  \x1B[32muser get <name|token>\x1B[0m        Display user details, subscription URL, and QR code
  \x1B[32muser delete <name|token>\x1B[0m     Remove user from Xray and delete from DB
  \x1B[32muser reset-traffic <name>\x1B[0m    Reset traffic usage counter for user

  \x1B[32mnode list\x1B[0m                    List all configured Xray nodes
  \x1B[32mhelp\x1B[0m                         Show this help message

\x1B[1mFLAGS:\x1B[0m
  --email <email>              Specify custom email address
  --sub-name <name>            Specify device or subscription name
  --no-qr                      Suppress terminal QR code output
`);
}
async function handleStatus() {
  console.log("\x1B[1m\x1B[36m--- NadamuDash System Status ---\x1B[0m");
  try {
    const start = Date.now();
    await db_default.$queryRaw`SELECT 1`;
    const latency = Date.now() - start;
    console.log(`\x1B[32m\u2714 PostgreSQL:\x1B[0m Connected (${latency}ms)`);
  } catch (err) {
    console.log(`\x1B[31m\u2716 PostgreSQL:\x1B[0m Failed (${err.message})`);
  }
  try {
    const nodes = await db_default.node.findMany();
    console.log(`\x1B[32m\u2714 Configured Nodes:\x1B[0m ${nodes.length}`);
    for (const node of nodes) {
      const start = Date.now();
      const tags = await getXrayInboundTags(node.apiHost);
      const latency = Date.now() - start;
      if (tags.length > 0) {
        console.log(
          `  \u2022 Node \x1B[1m${node.name}\x1B[0m (${node.apiHost}): \x1B[32mONLINE\x1B[0m (${latency}ms) | Inbounds: [${tags.join(", ")}]`
        );
      } else {
        console.log(
          `  \u2022 Node \x1B[1m${node.name}\x1B[0m (${node.apiHost}): \x1B[31mOFFLINE or No Inbounds\x1B[0m`
        );
      }
    }
  } catch (err) {
    console.log(`\x1B[31m\u2716 Nodes/Xray Check Error:\x1B[0m ${err.message}`);
  }
  try {
    const userCount = await db_default.user.count();
    const subCount = await db_default.subscription.count();
    console.log(`\x1B[32m\u2714 Total Users:\x1B[0m ${userCount} (Subscriptions: ${subCount})`);
  } catch {
  }
}
async function handleSync() {
  console.log("\x1B[1mStarting gRPC reconciliation sync with Xray nodes...\x1B[0m");
  const results = await syncAllNodesService();
  for (const r of results) {
    console.log(
      `Node \x1B[1m${r.nodeName}\x1B[0m: Synced \x1B[32m${r.synced}\x1B[0m / ${r.total} active UUIDs to Xray in-memory state.`
    );
  }
  console.log("\x1B[32m\u2714 Reconciliation complete. Xray memory is in sync with database.\x1B[0m");
}
async function handleUserList() {
  const users = await listUsersService();
  if (users.length === 0) {
    console.log("No users found. Create one using: \x1B[32mdashctl user add <name>\x1B[0m");
    return;
  }
  console.log(
    `\x1B[1m%-16s %-24s %-38s %-12s %-12s\x1B[0m`,
    "NAME",
    "EMAIL",
    "TOKEN",
    "TRAFFIC",
    "ROLE"
  );
  console.log("\u2500".repeat(105));
  for (const u of users) {
    const token = u.subscriptions[0]?.token || "no-subscription";
    const trafficStr = formatBytes(u.totalBytes);
    console.log(
      `%-16s %-24s %-38s %-12s %-12s`,
      u.name.slice(0, 15),
      u.email.slice(0, 23),
      token,
      trafficStr,
      u.role
    );
  }
}
async function handleUserAdd(args) {
  const name = args[0];
  if (!name) {
    console.error("\x1B[31mError:\x1B[0m Name argument is required. Usage: dashctl user add <name> [--email <email>]");
    process.exit(1);
  }
  let email;
  let subName;
  for (let i = 1; i < args.length; i++) {
    if (args[i] === "--email" && args[i + 1]) {
      email = args[i + 1];
      i++;
    } else if (args[i] === "--sub-name" && args[i + 1]) {
      subName = args[i + 1];
      i++;
    }
  }
  console.log(`Creating user \x1B[1m${name}\x1B[0m...`);
  const result = await createUserService({ name, email, subName });
  console.log("\x1B[32m\u2714 User created successfully!\x1B[0m");
  console.log(`  \u2022 ID:            ${result.user.id}`);
  console.log(`  \u2022 Token:         \x1B[1m${result.subscription.token}\x1B[0m`);
  console.log(`  \u2022 Inbounds:      ${result.inbounds.length} provisioned in Xray`);
  const details = await getUserDetailsService(result.subscription.token);
  if (details) {
    console.log(`  \u2022 Sub URL:       \x1B[36m${details.subUrl}\x1B[0m
`);
    if (!args.includes("--no-qr")) {
      console.log("\x1B[1mSubscription QR Code (Scan in Clash / Sing-box / Shadowrocket):\x1B[0m");
      const qrAscii = await renderQr(details.subUrl);
      console.log(qrAscii);
    }
  }
}
async function handleUserGet(identifier, flags = []) {
  if (!identifier) {
    console.error("\x1B[31mError:\x1B[0m Identifier (name, email, or token) is required.");
    process.exit(1);
  }
  const details = await getUserDetailsService(identifier);
  if (!details) {
    console.error(`\x1B[31mError:\x1B[0m User or subscription not found for "${identifier}".`);
    process.exit(1);
  }
  console.log("\x1B[1m\x1B[36m--- User & Subscription Details ---\x1B[0m");
  console.log(`  \u2022 User:          ${details.user.name || "Unnamed"} (${details.user.email || "\u2014"})`);
  console.log(`  \u2022 User ID:       ${details.user.id}`);
  console.log(`  \u2022 Sub Name:      ${details.subscription.name}`);
  console.log(`  \u2022 Sub Token:     \x1B[1m${details.subscription.token}\x1B[0m`);
  console.log(`  \u2022 Sub URL:       \x1B[36m${details.subUrl}\x1B[0m`);
  console.log(
    `  \u2022 Traffic:       Up: ${formatBytes(details.traffic.up)} | Down: ${formatBytes(
      details.traffic.down
    )} | Total: \x1B[1m${formatBytes(details.traffic.total)}\x1B[0m`
  );
  console.log(`  \u2022 Created:       ${details.subscription.createdAt.toISOString()}`);
  if (details.links.length > 0) {
    console.log("\n\x1B[1mDirect VLESS Connection Links:\x1B[0m");
    for (const l of details.links) {
      console.log(`  [${l.tag} @ ${l.nodeName}]:`);
      console.log(`  \x1B[33m${l.link}\x1B[0m
`);
    }
  }
  if (!flags.includes("--no-qr")) {
    console.log("\x1B[1mSubscription QR Code:\x1B[0m");
    const qrAscii = await renderQr(details.subUrl);
    console.log(qrAscii);
  }
}
async function handleUserDelete(identifier) {
  if (!identifier) {
    console.error("\x1B[31mError:\x1B[0m Identifier (name, email, or token) is required.");
    process.exit(1);
  }
  console.log(`Removing user "${identifier}" from Xray and database...`);
  const res = await deleteUserService(identifier);
  if (res.success) {
    console.log(`\x1B[32m\u2714 User "${res.deletedUser}" deleted successfully.\x1B[0m`);
  } else {
    console.error(`\x1B[31mError:\x1B[0m ${res.error}`);
  }
}
async function handleUserResetTraffic(identifier) {
  if (!identifier) {
    console.error("\x1B[31mError:\x1B[0m Identifier is required.");
    process.exit(1);
  }
  const res = await resetUserTrafficService(identifier);
  if (res.success) {
    console.log(`\x1B[32m\u2714 Traffic reset successfully for "${identifier}".\x1B[0m`);
  } else {
    console.error(`\x1B[31mError:\x1B[0m ${res.error}`);
  }
}
async function handleNodeList() {
  const nodes = await db_default.node.findMany({
    include: {
      _count: {
        select: { inbounds: true, subscriptions: true }
      }
    }
  });
  if (nodes.length === 0) {
    console.log("No nodes registered in database.");
    return;
  }
  console.log(
    `\x1B[1m%-16s %-22s %-8s %-8s %-10s %-10s\x1B[0m`,
    "NAME",
    "ADDRESS",
    "PORT",
    "INTERNAL",
    "STATUS",
    "USERS"
  );
  console.log("\u2500".repeat(85));
  for (const n of nodes) {
    console.log(
      `%-16s %-22s %-8d %-8d %-10s %-10d`,
      n.name.slice(0, 15),
      n.address.slice(0, 21),
      n.port,
      n.xrayPort,
      n.isActive ? "\x1B[32mActive\x1B[0m" : "\x1B[31mDisabled\x1B[0m",
      n._count.subscriptions
    );
  }
}
async function main() {
  const args = process.argv.slice(2);
  const command = args[0];
  try {
    switch (command) {
      case "status":
        await handleStatus();
        break;
      case "sync":
        await handleSync();
        break;
      case "user":
      case "users": {
        const subCmd = args[1];
        if (subCmd === "list" || !subCmd) {
          await handleUserList();
        } else if (subCmd === "add") {
          await handleUserAdd(args.slice(2));
        } else if (subCmd === "get") {
          await handleUserGet(args[2], args.slice(3));
        } else if (subCmd === "delete" || subCmd === "revoke" || subCmd === "rm") {
          await handleUserDelete(args[2]);
        } else if (subCmd === "reset-traffic") {
          await handleUserResetTraffic(args[2]);
        } else {
          console.error(`Unknown user subcommand: ${subCmd}`);
          printHelp();
        }
        break;
      }
      case "node":
      case "nodes":
        await handleNodeList();
        break;
      case "help":
      case "--help":
      case "-h":
      case void 0:
        printHelp();
        break;
      default:
        console.error(`Unknown command: ${command}`);
        printHelp();
        process.exit(1);
    }
  } catch (err) {
    console.error("\x1B[31mFatal error:\x1B[0m", err);
    process.exit(1);
  } finally {
    await db_default.$disconnect();
  }
}
main();
